type Updater interface{ Update(dt float64) }

type Entity struct {
    Pos   Vec2
    parts []Updater
}

func (e *Entity) Add(u Updater)      { e.parts = append(e.parts, u) }
func (e *Entity) Update(dt float64) {
    for _, p := range e.parts {
        p.Update(dt)
    }
}

